    primarySources:[{href:"https://www.royalnavy.mod.uk/news/2023/december/11/20231211-monument-dedicated-in-malaysia-to-the-prince-of-wales-and-repulse-tragedy",label:"Royal Navy — casualties and Kuantan memorial"},{href:"https://www.history.navy.mil/content/history/museums/nmusn/explore/photography/wwii/wwii-pacific/us-entry-into-wwii-japanese-offensive/1941-december-10-loss-hms-prince-of-wales-hms-repulse.html",label:"US Naval History — loss of the two capital ships"},{href:"https://cd.royalnavy.mod.uk/-/media/rnweb/locations-and-operations/navy-historical-branch/pdfs/1941/war_diary_naval_1941_12-day-1-to-day-15.pdf",label:"Royal Navy Historical Branch — December 1941 war diary"},{href:"https://en.wikipedia.org/wiki/Sinking_of_Prince_of_Wales_and_Repulse",label:"Wikipedia — detailed historical action"}],
